      getStockAnalysis(stockCode) {
        const risingStocks = this.db.prepare(`
            SELECT 
                date, 
                '\uC218\uAE09 \uAE09\uB4F1\uC8FC AI' as agent_type, 
                ai_score as score, 
                reason, 
                chart_insight, 
                past_reference,
                date || ' ' || timing as sort_time
            FROM daily_rising_stocks 
            WHERE stock_code = ?
        `).all(stockCode);
        const analystPicks = this.db.prepare(`
            SELECT 
                date, 
                agent_type, 
                confidence as score, 
                reason, 
                null as chart_insight, 
                null as past_reference,
                created_at as sort_time
            FROM ai_analyst_picks 
            WHERE stock_code = ?
        `).all(stockCode);
        const combined = [...risingStocks, ...analystPicks.map((p2) => ({
          ...p2,
          agent_type: p2.agent_type === "THEME" ? "\uD14C\uB9C8 AI" : p2.agent_type === "REPORT" ? "\uB9AC\uD3EC\uD2B8 AI" : p2.agent_type === "MOMENTUM" ? "\uC218\uAE09 AI (\uBAA8\uBA58\uD140)" : p2.agent_type
        }))];
        combined.sort((a2, b) => b.sort_time.localeCompare(a2.sort_time));
        return combined;
      }
