      async getAllStocks(marketType) {
        const cacheKey = `ALL_STOCKS_${marketType}`;
        const cached = this.cacheStore.get(cacheKey);
        const dayInMs = 24 * 60 * 60 * 1e3;
        if (cached && Date.now() - cached.timestamp < dayInMs) {
          console.log(`[KiwoomService] Using cached stock list for ${marketType}`);
          return cached.data;
        }
        console.log(`[KiwoomService] Fetching all stocks from Kiwoom API for market ${marketType}...`);
        const url2 = `${BASE_URL}/api/dostk/stkinfo`;
        let allStocks = [];
        let hasMore = true;
        let nextKey = "";
        while (hasMore) {
          try {
            const response = await this.makeApiRequestWithRetry((t2) => this.kiwoomAxios.post(url2, {
              mrkt_tp: marketType
            }, {
              headers: {
                "Content-Type": "application/json;charset=UTF-8",
                "authorization": `Bearer ${t2}`,
                "api-id": "ka10099",
                "cont-yn": nextKey ? "Y" : "N",
                "next-key": nextKey
              }
            }));
            const data = response.data;
            const list = data?.Body || data?.list || [];
            allStocks = allStocks.concat(list);
            nextKey = response.headers["next-key"] || "";
            hasMore = response.headers["cont-yn"] === "Y" && !!nextKey;
            if (hasMore) await new Promise((resolve) => setTimeout(resolve, 150));
          } catch (err) {
            console.error(`[KiwoomService] Failed to fetch stock list chunk:`, err);
            hasMore = false;
          }
        }
        const result = allStocks.map((s2) => ({
          stock_code: (s2.stck_shrn_iscd || s2.code || "").replace(/[^0-9A-Z]/g, ""),
          stock_name: s2.stck_nm || s2.name || ""
        }));
        if (result.length > 0) {
          this.cacheStore.set(cacheKey, {
            data: result,
            timestamp: Date.now(),
            ttl: dayInMs
          });
        }
        return result;
      }
