    let score = 0;
    const vwapGap = (state.currentPrice - state.vwap) / state.vwap * 100;
    let vwapScore = 0;
    if (vwapGap >= 0 && vwapGap <= 2) vwapScore = weights.vwap;
    else if (vwapGap > 2 && vwapGap <= 5) vwapScore = weights.vwap * 0.5;
    else if (vwapGap > 5 && vwapGap <= 10) vwapScore = weights.vwap * 0.25;
    score += vwapScore;
