import_electron6.ipcMain.handle("maiis:run-pipeline-manual", async (_event, pipelineId) => {
  try {
    console.log(`[Main] Manual pipeline trigger: ${pipelineId}`);
    switch (pipelineId) {
      case "PRE_MARKET":
        await schedulerService.runPreMarketAnalysis();
        break;
      case "AM_EXECUTION":
        await schedulerService.runPendingExecution();
        break;
      case "MORNING":
        await schedulerService.runMorningPipeline();
        break;
      case "INTRADAY":
        await schedulerService.runIntradayReview();
        break;
      case "EVENING":
        await schedulerService.runEveningPipeline();
        break;
      case "CLOSING":
        await schedulerService.runClosingReview();
        break;
      default:
        return { success: false, error: `Unknown pipeline: ${pipelineId}` };
    }
    return { success: true };
  } catch (error) {
    console.error(`[Main] Manual pipeline ${pipelineId} error:`, error);
    return { success: false, error: error.message };
  }
});
