import_electron6.ipcMain.handle("v2:get-market-leaders", async (_event, { days, topN }) => {
  try {
    const { MarketLeaderDiscoveryService: MarketLeaderDiscoveryService2 } = await Promise.resolve().then(() => (init_MarketLeaderDiscoveryService(), MarketLeaderDiscoveryService_exports));
    const { getPastDateKst: getPastDateKst2 } = await Promise.resolve().then(() => (init_DateUtils(), DateUtils_exports));
    const DatabaseService2 = (await Promise.resolve().then(() => (init_DatabaseService(), DatabaseService_exports))).DatabaseService;
    const db = DatabaseService2.getInstance().db;
    const targetDays = days ?? 10;
    const targetDate = getPastDateKst2(targetDays);
    let marketIndexChange = 0;
    try {
      const kodexRows = db.prepare(`SELECT close FROM market_ohlcv_history WHERE stock_code='069500' AND date >= ? ORDER BY date ASC`).all(targetDate);
      if (kodexRows && kodexRows.length > 0) {
        const first = kodexRows[0].close;
        const last = kodexRows[kodexRows.length - 1].close;
        if (first > 0) {
          marketIndexChange = (last - first) / first * 100;
        }
      }
    } catch (e2) {
    }
    const service = MarketLeaderDiscoveryService2.getInstance();
    const leaders = service.getMarketLeaders(targetDays, marketIndexChange, topN ?? 30);
    const themes = service.discoverMainThemes(leaders);
    console.log(`[MarketLeader] days=${targetDays}, KODEX=${marketIndexChange.toFixed(2)}%, leaders=${leaders.length}, themes=${themes.length}`);
    return { success: true, leaders, themes, marketIndexChange };
  } catch (error) {
    console.error("[MarketLeader] get-market-leaders error:", error);
    return { success: false, error: error.message, leaders: [], themes: [] };
  }
});
