import_electron6.ipcMain.handle("naverflow:get-settings", async () => {
  const raw = store18.get("naverflow_settings") || { enabled: false, scheduleSlots: [{ time: "09:30", enabled: true }, { time: "15:30", enabled: true }] };
  let changed = false;
  if (raw && Array.isArray(raw.scheduleSlots)) {
    raw.scheduleSlots = raw.scheduleSlots.map((s2) => {
      if (s2.time === "09:30") {
        changed = true;
        return { ...s2, time: "09:40" };
      }
      if (s2.time === "15:30") {
        changed = true;
        return { ...s2, time: "15:45" };
      }
      return s2;
    });
  }
  if (changed) {
    store18.set("naverflow_settings", raw);
  }
  return raw;
});
