import_electron6.ipcMain.handle("naverflow:search-live-news", async (_event, keyword) => {
  try {
    const { NaverSearchCollector: NaverSearchCollector2 } = await Promise.resolve().then(() => (init_NaverSearchCollector(), NaverSearchCollector_exports));
    const { DatabaseService: DatabaseService2 } = await Promise.resolve().then(() => (init_DatabaseService(), DatabaseService_exports));
    const collector = new NaverSearchCollector2();
    const rawSearch = await collector.collect({ keyword });
    const dbSvc = DatabaseService2.getInstance();
    const rawDb = dbSvc.db;
    const now = /* @__PURE__ */ new Date();
    const dateStr = dbSvc.getKstDate();
    const timeBucket = `${String(now.getHours()).padStart(2, "0")}:${String(now.getMinutes()).padStart(2, "0")}`;
    const stmtInsertNews = rawDb.prepare(`
            INSERT INTO naver_news_flow
                (date, category, title, body_snippet, source, article_id, url, collected_at, time_bucket, article_hash, search_keyword)
            VALUES
                (@date, @category, @title, @body_snippet, @source, @article_id, @url, @collected_at, @time_bucket, @article_hash, @search_keyword)
        `);
    const formattedList = (rawSearch?.articles || []).map((item) => {
      const title = item.title?.replace(/<[^>]+>/g, "") || "";
      const snippet = item.description?.replace(/<[^>]+>/g, "") || "";
      let source = "NaverSearchAPI";
      try {
        source = item.originallink ? new URL(item.originallink).hostname.replace("www.", "") : "Naver";
      } catch (e2) {
      }
      const pubDate = item.pubDate ? new Date(item.pubDate).toISOString() : now.toISOString();
      const url2 = item.originallink || item.link || "";
      const hash = Math.abs(Math.imul(31, 0) + title.charCodeAt(0) | 0).toString(16) + (item.pubDate || Date.now());
      try {
        stmtInsertNews.run({
          date: dateStr,
          category: "THEME_TARGET_MANUAL",
          // 연관 뉴스 캐시에 걸리도록 통합
          title,
          body_snippet: snippet,
          source,
          article_id: hash,
          url: url2,
          collected_at: now.toISOString(),
          time_bucket: timeBucket,
          article_hash: hash,
          search_keyword: keyword
        });
      } catch (e2) {
      }
      return {
        title,
        source,
        date: pubDate,
        url: url2,
        category: "LIVE_SEARCH_MANUAL"
      };
    });
    return { success: true, data: formattedList };
  } catch (err) {
    return { success: false, error: err.message };
  }
});
